import { CONFIG } from './config.js';
import { button, dialog, escapeHTML as esc } from './ui.js';
import { bindGesture } from './input.js';

export function mountGame(kind, root, state, save, complete, effects, sound, life) {
  const index=['stars','hunt','reaction'].indexOf(kind);
  const cfg=CONFIG.games[kind];let finished=false;let running=false;
  const names=['接住生日星星','寻找隐藏礼物','按住，等一束光'];
  const hints=[`在${cfg.seconds}秒里，收集${cfg.target}颗星星。左右移动星篮，把落下的光接住。`,'拖动月亮、拨开云朵、拉开礼物盒，找出三份惊喜。也可以轻点探索。','按住光团为它蓄光。变成金色、出现“松手”时放开，一共五次。'];
  root.innerHTML=`<div class="game-heading"><div><p class="eyebrow">生日任务 · 第${['一','二','三'][index]}站</p><h2>${names[index]}</h2><p class="subtext">${hints[index]}</p></div><div class="energy-small"><span>生日能量</span><strong>${state.completed.length} <small>／ 三份</small></strong></div></div><div class="game-panel"><div class="game-stats"><span id="game-count"></span><span id="game-time"></span></div><div id="arena" class="arena ${kind}" aria-label="${names[index]}游戏区域"></div><p id="game-message" class="game-message" role="status"></p><div class="game-actions" id="game-actions"></div></div><div class="game-help"><span id="help-message" class="hint">没有输赢的小任务，开心最重要。</span>${button('help','help','','text-button')}<span id="skip-slot"></span></div>`;
  const arena=root.querySelector('#arena'),count=root.querySelector('#game-count'),time=root.querySelector('#game-time'),message=root.querySelector('#game-message'),actions=root.querySelector('#game-actions');
  const helpStatus=()=>{if(state.attempts[kind]>=CONFIG.games.helpAfter){root.querySelector('#help-message').textContent='今天是生日，就不为难你了。';root.querySelector('#skip-slot').innerHTML=button('claim','claim','','secondary');root.querySelector('#claim').onclick=()=>finish(true)}};
  root.querySelector('#help').onclick=()=>{state.attempts[kind]++;save();root.querySelector('#help-message').textContent=kind==='hunt'?'小提示：看看月亮、云朵，再多点一次礼物盒。':'可以慢慢试，也可以再点一次帮助，直接领取能量。';helpStatus()};helpStatus();
  function finish(skipped=false){if(finished)return;finished=true;running=false;complete(index);root.querySelector('.energy-small strong').innerHTML=`${state.completed.length} <small>／ 三份</small>`;if(!count.textContent)count.textContent='本关的祝福已收下';effects.burst(innerWidth/2,innerHeight*.4,true);sound.play(784);arena.innerHTML=`<div class="game-result"><span class="result-star" aria-hidden="true">✦</span><h3>${['第一份生日能量已经获得。','第二份生日能量已经获得。','生日任务全部完成。'][index]}</h3><p>${skipped?'这是今天的特别通行证。所有美好，一份也不会少。':['你看，星星真的可以被你抓住。','愿生活里，也常常藏着这样的小惊喜。','无论快慢，你都能赶上属于自己的光。'][index]}</p></div>`;message.textContent='';time.textContent='已完成';actions.innerHTML=button('next','game-next');root.querySelector('#game-next').onclick=()=>root.dispatchEvent(new CustomEvent('game-next',{bubbles:true}));root.querySelector('.game-help').classList.add('hidden');root.querySelector('#game-next').focus({preventScroll:true});}
  if(state.completed.includes(index)){finish();return}
  if(kind==='stars'){
    let collected=0,remaining=cfg.seconds*1000,lastTick=performance.now(),spawnClock=0,basket=50,direction=0,falling=[];
    const update=()=>{count.textContent=`已经收集：${collected} ／ ${cfg.target}`;time.textContent=`剩余 ${Math.ceil(remaining/1000)} 秒`};
    function setBasket(x){basket=Math.min(93,Math.max(7,x));const el=arena.querySelector('.star-basket');if(el)el.style.left=`${basket}%`;}
    function start(){collected=0;remaining=cfg.seconds*1000;falling=[];spawnClock=cfg.spawnMs;running=true;lastTick=performance.now();update();arena.classList.add('playing');arena.tabIndex=0;arena.setAttribute('aria-label','左右移动星篮接住落下的星星，可使用左右方向键');arena.innerHTML='<div class="basket-guide" aria-hidden="true"></div><div class="star-basket" aria-hidden="true">星光口袋</div>';setBasket(50);message.textContent=effects.reduced?'星光会停在空中等你，移动星篮对准它。':'在场景中左右滑动，或使用下方按钮、键盘方向键移动。';actions.innerHTML='<div class="move-controls"><button class="secondary" id="move-left" aria-label="向左移动星篮">向左</button><button class="secondary" id="move-right" aria-label="向右移动星篮">向右</button></div>';
      for(const [id,d] of [['move-left',-1],['move-right',1]]){const el=root.querySelector('#'+id);bindGesture(el,{signal:life.signal,start:()=>{direction=d},end:()=>{direction=0},cancel:()=>{direction=0}});el.onclick=()=>setBasket(basket+d*9);}
      arena.focus({preventScroll:true});
    }
    function end(){running=false;direction=0;arena.classList.remove('playing');state.attempts.stars++;save();helpStatus();arena.innerHTML='<div class="arena-intro"><span aria-hidden="true">✧</span><h3>差一点点，再试一次。</h3><p>星篮已经准备好，下一场流星雨就要来了。</p></div>';actions.innerHTML=button('retry','retry');root.querySelector('#retry').onclick=start;message.textContent='没有惩罚，也可以领取今天的特别通行证。';}
    function move(e){if(!running)return;const r=arena.getBoundingClientRect();setBasket((e.clientX-r.left)/r.width*100)}
    bindGesture(arena,{signal:life.signal,enabled:()=>running,start:move,move});arena.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')move(e)},{signal:life.signal});window.addEventListener('blur',()=>{direction=0},{signal:life.signal});
    document.addEventListener('keydown',e=>{if(!running||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();direction=e.key==='ArrowLeft'?-1:1},{signal:life.signal});document.addEventListener('keyup',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key))direction=0},{signal:life.signal});
    life.every(()=>{const now=performance.now(),dt=Math.min(now-lastTick,150);lastTick=now;if(!running||finished||document.hidden)return;remaining=Math.max(0,remaining-dt);setBasket(basket+direction*dt*.07);spawnClock+=dt;const h=arena.clientHeight,w=arena.clientWidth;
      if(spawnClock>=cfg.spawnMs&&(!effects.reduced||falling.length===0)){spawnClock=0;const el=document.createElement('span');el.className='falling-star';el.setAttribute('aria-hidden','true');el.textContent='✦';const star={x:12+Math.random()*76,y:effects.reduced?h*.55:10,el};el.style.left=`${star.x}%`;arena.append(el);falling.push(star)}
      falling=falling.filter(star=>{if(!effects.reduced)star.y+=dt/(cfg.fallSeconds*1000)*(h-30);star.el.style.top=`${star.y}px`;const near=Math.abs(star.x-basket)*w/100<56;if((effects.reduced||star.y>=h-45)&&near){star.el.remove();collected++;const r=arena.getBoundingClientRect();effects.burst(r.left+basket*w/100,r.top+h-35);sound.play([523,659,784][collected%3]);return false}if(star.y>h-15){star.el.remove();return false}return true});update();if(collected>=cfg.target){arena.classList.remove('playing');finish()}else if(remaining<=0)end();
    },40);
    document.addEventListener('visibilitychange',()=>{lastTick=performance.now();direction=0},{signal:life.signal});
    update();arena.innerHTML='<div class="arena-intro"><span aria-hidden="true">✧</span><h3>这一场流星雨，等你来接。</h3><p>用手指、鼠标或方向键，左右移动你的星光口袋。</p></div>';actions.innerHTML=button('start','game-start');root.querySelector('#game-start').onclick=start;
  }else if(kind==='hunt'){
    const objects=[['moon','月亮','☾',0],['planet','小星球','',-1],['cloud','云朵','',1],['lamp','小灯','',-1],['box','礼物盒','',2],['tiny-star','远方的星星','✧',-1]];
    const refresh=()=>{count.textContent=`已经发现：${state.found.length} ／ ${cfg.target}`;time.textContent='慢慢找，不计时';arena.querySelectorAll('[data-object]').forEach(el=>{const found=state.found.includes(Number(el.dataset.gift));el.classList.toggle('found',found);el.setAttribute('aria-label',`${el.dataset.name}${found?'，已发现礼物':''}`);el.querySelector('.object-state').textContent=found?'已发现':'拖开看看';el.disabled=found})};
    arena.innerHTML=objects.map(([type,name,symbol,id],i)=>`<button class="hunt-object ${type}" data-object="${i}" data-gift="${id}" data-name="${name}"><span class="object-drawing" aria-hidden="true">${symbol}${type==='box'?'<i></i>':''}</span><span class="object-name">${name}</span><span class="object-state">轻点探索</span></button>`).join('');
    arena.querySelectorAll('[data-object]').forEach(el=>{let dragged=false,startX=0,startY=0,active=false;const art=el.querySelector('.object-drawing');const reveal=()=>{if(finished)return;const id=Number(el.dataset.gift);if(id<0){message.textContent=el.dataset.name==='小星球'?'这颗小星球正在休假，礼物藏在别的地方。':'这里有一束光，先送给你。再看看别处吧。';return}if(state.found.includes(id))return;if(id===2&&!state.fakeOpened){state.fakeOpened=true;save();message.textContent='这个里面什么都没有。';life.after(()=>{if(!finished&&!state.found.includes(2))message.textContent='骗你的，再点一次。'},1100);return}state.found.push(id);save();refresh();sound.play(659);const r=el.getBoundingClientRect();effects.burst(r.x+r.width/2,r.y+r.height/3);message.textContent=(id===2?'一份好运送给你。':'')+['发现第一份小惊喜。','又找到一个。','全部找到。'][state.found.length-1];const blessing=CONFIG.gameBlessings.hunt[id];dialog(blessing.title,`<p class="game-blessing">${esc(blessing.text)}</p>`,{onClose:()=>{if(state.found.length>=cfg.target)finish()}})};el.onclick=()=>{if(dragged){dragged=false;return}reveal()};bindGesture(el,{signal:life.signal,enabled:()=>!el.disabled,start:e=>{active=true;dragged=false;startX=e.clientX;startY=e.clientY;art.classList.add('dragging')},move:e=>{if(active)art.style.transform=`translate(${Math.max(-65,Math.min(65,e.clientX-startX))}px,${Math.max(-40,Math.min(40,e.clientY-startY))}px)`},end:e=>{active=false;art.classList.remove('dragging');art.style.transform='';if(Math.hypot(e.clientX-startX,e.clientY-startY)>=cfg.dragDistance){dragged=true;reveal()}},cancel:()=>{active=false;dragged=false;art.classList.remove('dragging');art.style.transform=''}});});
    refresh();message.textContent='有些惊喜，需要多一点点好奇心。';if(state.found.length>=cfg.target)finish();
  }else{
    let holding=false,ready=false,serial=0,appearedAt=0,tapMode=false;
    const update=()=>{count.textContent=`已经完成：${state.rounds.length} ／ ${cfg.rounds}`;time.textContent='按住蓄光 · 亮起松手'};
    function miss(text){if(finished)return;serial++;holding=false;ready=false;running=false;state.attempts.reaction++;save();helpStatus();message.textContent=text;const orb=arena.querySelector('.hold-zone');if(orb){orb.classList.remove('charging','ready');orb.querySelector('small').textContent=tapMode?'轻点开始':'按住蓄光';orb.setAttribute('aria-label',tapMode?'轻点开始蓄光':'按住蓄光，亮起时松手')}}
    function release(){if(!holding||finished)return;holding=false;if(!ready){miss('再多等一会儿，金色的光还没准备好。');return}ready=false;running=false;serial++;const elapsed=Math.round(performance.now()-appearedAt);state.rounds.push(elapsed);save();update();effects.burst(innerWidth/2,innerHeight*.45);sound.play(784);arena.innerHTML=`<div class="reaction-feedback"><span aria-hidden="true">✧</span><h3>${elapsed<650?'这次反应相当可以。':elapsed<1300?'不错，刚刚好。':'你接住了属于自己的光。'}</h3><p>第${['一','二','三','四','五'][state.rounds.length-1]||state.rounds.length}束光，已收到。</p></div>`;const blessing=CONFIG.gameBlessings.reaction[(state.rounds.length-1)%CONFIG.gameBlessings.reaction.length];arena.innerHTML=`<div class="reaction-feedback blessing-reward"><span aria-hidden="true">✧</span><h3>${esc(blessing.title)}</h3><p class="game-blessing">${esc(blessing.text)}</p></div>`;message.textContent='这一束光，也是一份认真送给你的祝福。';actions.innerHTML=button('close','blessing-next');root.querySelector('#blessing-next').onclick=next}
    function begin(){if(holding||finished||!arena.querySelector('.hold-zone'))return;holding=true;running=true;ready=false;const token=++serial;const orb=arena.querySelector('.hold-zone');orb.classList.add('charging');orb.querySelector('small').textContent='继续蓄光';message.textContent='别急，让光慢慢聚起来。';life.after(()=>{if(token!==serial||!holding||finished)return;ready=true;appearedAt=performance.now();orb.classList.add('ready');orb.querySelector('small').textContent=tapMode?'现在轻点':'现在松手';orb.setAttribute('aria-label',tapMode?'现在轻点收光':'现在松手收光');message.textContent=tapMode?'金色的光亮了，轻点收下它！':'金色的光亮了，现在松手！';sound.play(880);life.after(()=>{if(token===serial&&ready)miss('光先去散步了。已经收到的会保留，再试一次吧。')},cfg.releaseWindow)},cfg.minDelay+Math.random()*(cfg.maxDelay-cfg.minDelay))}
    function next(){if(finished)return;if(state.rounds.length>=cfg.rounds){finish();return}ready=false;holding=false;running=false;update();arena.innerHTML=`<div class="hold-wrap"><button class="hold-zone" aria-label="${tapMode?'轻点开始蓄光':'按住蓄光，亮起时松手'}"><span aria-hidden="true">✧</span><small>${tapMode?'轻点开始':'按住蓄光'}</small></button></div>`;message.textContent=tapMode?'先轻点蓄光，等变成金色再轻点一次。':'按住光团，等“现在松手”出现。';actions.innerHTML=`<button id="input-mode" class="text-button">${tapMode?'切回按住模式':'不方便长按？使用轻触模式'}</button>`;root.querySelector('#input-mode').onclick=()=>{serial++;tapMode=!tapMode;next()};const orb=arena.querySelector('.hold-zone');
      bindGesture(orb,{signal:life.signal,enabled:()=>!tapMode,start:e=>{e.preventDefault();begin()},end:release,cancel:()=>{if(holding)miss('刚刚暂停了，再按住一次就好。')}});orb.oncontextmenu=e=>e.preventDefault();
      orb.onkeydown=e=>{if(![' ','Enter'].includes(e.key)||e.repeat||tapMode)return;e.preventDefault();begin()};orb.onkeyup=e=>{if(![' ','Enter'].includes(e.key)||tapMode)return;e.preventDefault();release()};orb.onclick=()=>{if(tapMode){if(holding)release();else begin()}};
    }
    window.addEventListener('blur',()=>{if(holding)miss('光会等你，回来后再按住一次就好。')},{signal:life.signal});document.addEventListener('visibilitychange',()=>{if(document.hidden&&holding){serial++;holding=false;ready=false;next();message.textContent='光会等你回来，准备好再开始。'}},{signal:life.signal});update();next();
  }
}
